// Generated by Automated Quality Gate; review before merging.
const { add, subtract, multiply, divide, addDecimals } = require('../src/math');

describe('Math Module Unit Tests', () => {
  
  describe('add', () => {
    test('should correctly add two positive integers', () => {
      expect(add(2, 3)).toBe(5);
    });

    test('should correctly add negative numbers', () => {
      expect(add(-1, -1)).toBe(-2);
    });
  });

  describe('subtract', () => {
    test('should correctly subtract two numbers', () => {
      expect(subtract(10, 5)).toBe(5);
    });

    test('should return a negative result when subtracting a larger number', () => {
      expect(subtract(5, 10)).toBe(-5);
    });
  });

  describe('multiply', () => {
    test('should correctly multiply two numbers', () => {
      expect(multiply(3, 4)).toBe(12);
    });

    test('should return 0 when multiplying by 0', () => {
      expect(multiply(5, 0)).toBe(0);
    });
  });

  describe('divide', () => {
    test('should correctly divide two numbers', () => {
      expect(divide(10, 2)).toBe(5);
    });

    test('should throw an error when dividing by zero', () => {
      expect(() => {
        divide(10, 0);
      }).toThrow('Cannot divide by zero');
    });

    test('should handle decimal division', () => {
      expect(divide(5, 2)).toBe(2.5);
    });
  });

  describe('addDecimals', () => {
    test('should correctly add two decimal numbers', () => {
      expect(addDecimals(0.1, 0.2)).toBeCloseTo(0.3);
    });

    test('should correctly add positive and negative decimals', () => {
      expect(addDecimals(0.5, -0.2)).toBeCloseTo(0.3);
    });
  });

});
